-- Review-gated NMDFC Term Loan, Micro-Finance and Virasat artisan records.

do $$
declare
  item jsonb;
  authority_id uuid;
  seed_opportunity_id uuid;
  version_id uuid;
begin
  for item in
    select value from jsonb_array_elements($records$[
      {"slug":"nmdfc-term-loan-employment-venture","name":"NMDFC Term Loan Scheme for Employment-Generating Ventures","type":"concessional_loan","status":"active","authority":"National Minorities Development and Finance Corporation - Term Loan Scheme","authority_url":"https://www.nmdfc.org/","canonical_url":"https://www.nmdfc.org/nmdfcschemes","source_url":"https://www.nmdfc.org/nmdfcschemes","source_kind":"agency","source_title":"NMDFC current schemes page","source_anchor":"Term Loan Scheme: notified minority communities, Credit Line 1/2 income limits, loan ceilings, interest, moratorium and repayment","summary":"Concessional credit for economically viable income-generating ventures of eligible persons from notified minority communities, routed through State Channelizing Agencies and banking partners.","objective":"Finance viable employment-generating ventures in agriculture and allied activities, technical trades, small business, artisan occupations, transport and services.","legal_basis":"NMDFC official schemes and FAQ pages under the administrative control of the Ministry of Minority Affairs; current SCA/banking-partner rules and lending policy control the live case.","eligibility":{"entity_types":["individual_minority_beneficiary","micro_business","small_business","artisan","service_provider","transport_operator"],"lifecycle_stages":["starting","operating","expanding"],"industries":["agriculture_and_allied","technical_trades","small_business","artisan_and_traditional_occupations","transport","services"],"locations":["India","rural_area","urban_area"],"conditions":["applicant must belong to a notified minority community: Muslim, Christian, Sikh, Buddhist, Parsi or Jain","Credit Line 1 applies to annual family income up to INR 3 lakh and Credit Line 2 applies to annual family income up to INR 8 lakh, subject to current policy confirmation","venture must be commercially viable and technically feasible under the selected route","application and appraisal are handled through State Channelizing Agencies or banking partners","credit line, project cost, beneficiary contribution, interest, moratorium and repayment terms must be selected and verified separately","women beneficiaries may receive the stated Credit Line 2 rate concession subject to current terms"],"thresholds":{"credit_line_1_annual_family_income_max_inr":300000,"credit_line_2_annual_family_income_max_inr":800000,"credit_line_1_loan_ceiling_inr":2000000,"credit_line_2_loan_ceiling_inr":3000000,"credit_line_2_women_rate_concession_percent":2,"beneficiary_repayment_max_years":5,"moratorium_months":6},"unknown_handling":"needs_information"},"application":{"portal":"https://www.nmdfc.org/nmdfcschemes","route":"Confirm the applicable credit line, prepare minority, income, residence, KYC and project evidence, and apply through the relevant State Channelizing Agency or banking partner.","selection":"The SCA or banking partner verifies eligibility, project viability, contribution, documentation and repayment capacity; UdyamVeda cannot approve or disburse the loan.","fees":"The reviewed sources do not establish a universal applicant fee. Interest, beneficiary contribution, processing, security, insurance and local SCA/bank charges must be confirmed for the selected route.","applicant_note":"UdyamVeda may explain and prepare the application checklist, but must not impersonate the applicant, collect OTPs or represent itself as NMDFC, an SCA or a bank."},"fine_print":{"credit_lines":"The current NMDFC schemes page describes Credit Line 1 up to INR 3 lakh annual family income with up to INR 20 lakh credit at 6% p.a., and Credit Line 2 up to INR 8 lakh annual family income with up to INR 30 lakh credit at 8% p.a. for male beneficiaries and 6% p.a. for women beneficiaries; the current policy and SCA terms must be reconciled.","funding_pattern":"The official pages describe an NMDFC:SCA:beneficiary pattern of 90:5:5 and a minimum beneficiary contribution, while the Credit Line 1 detail describes up to 90% of project cost and a minimum 5% beneficiary contribution; show these as funding conditions, not extra benefits.","repayment":"The current summary states a 6-month moratorium and 5-year beneficiary repayment period; confirm the current agreement, utilization period and SCA repayment terms.","route":"Applications are routed through State Channelizing Agencies and banking partners, not treated as a direct public NMDFC checkout flow.","review_note":"Human review must reconcile the current NMDFC scheme page, FAQ, Credit Line 1 detail, lending policy, current forms, SCA availability, project-cost rule, contribution, security, interest, moratorium, repayment and amendments before publication."},"benefit_summary":{"types":["loan"],"summary":"Track-specific concessional term credit for viable employment-generating ventures: current NMDFC pages describe up to INR 20 lakh under Credit Line 1 and up to INR 30 lakh under Credit Line 2, subject to income, project, contribution and SCA conditions.","separate_value_buckets":true},"benefit_type":"loan","benefit_label":"Track-specific NMDFC term credit: up to INR 20 lakh (Credit Line 1) or INR 30 lakh (Credit Line 2)","amount_min":null,"amount_max":3000000,"percentage":null,"benefit_conditions":{"credit_line_1_income_max_inr":300000,"credit_line_2_income_max_inr":800000,"credit_line_1_interest_percent":6,"credit_line_2_interest_percent_male":8,"credit_line_2_interest_percent_women":6,"beneficiary_repayment_years":5,"moratorium_months":6,"sca_route_required":true,"loan_not_guaranteed":true},"requirement":"Minority certificate, income/residence/KYC evidence and viable project documents","requirement_description":"Provide self-attested income certificate, residence proof, minority/religious certificate, identity/KYC records, project report where required, cost estimates, contribution evidence and SCA/bank forms.","rules":{"all":[{"field":"notified_minority_status_verified","operator":"equals","value":true},{"field":"annual_family_income_inr","operator":"less_than_or_equal","value":800000},{"field":"venture_commercially_viable","operator":"equals","value":true},{"field":"sca_or_banking_partner_route","operator":"equals","value":true}],"unknown_handling":"needs_information"},"steps":[{"title":"Select the correct NMDFC credit line","description":"Check annual family income, women-beneficiary concession, project cost and current Credit Line 1/2 terms without combining the ceilings.","url":"https://www.nmdfc.org/nmdfcschemes"},{"title":"Prepare minority and project documents","description":"Collect income, residence, minority, KYC, project, cost and contribution evidence required by the current SCA or bank.","url":"https://www.nmdfc.org/home/nmdfc_schemes"},{"title":"Apply through the channel partner","description":"Submit through the relevant State Channelizing Agency or banking partner and complete its appraisal and documentation process.","url":"https://www.nmdfc.org/faq"},{"title":"Complete disbursement and repayment setup","description":"Confirm the final sanction, interest, contribution, moratorium, utilization period, repayment schedule and post-disbursement obligations.","url":"https://www.nmdfc.org/nmdfcschemes"}],"window_type":"rolling","window_close_at":null,"window_label":"Rolling channel-finance route; local SCA/banking-partner availability and current policy must be confirmed.","window_evidence":{"source_url":"https://www.nmdfc.org/nmdfcschemes","anchor":"Current scheme page describes standing Term Loan Scheme terms and does not state a single nationwide closing date."},"review_note":"Keep review-gated. Do not present the two credit-line ceilings as a combined entitlement or guaranteed sanction."},
      {"slug":"nmdfc-micro-finance-shg","name":"NMDFC Micro-Finance Scheme for Minority SHGs","type":"microfinance","status":"active","authority":"National Minorities Development and Finance Corporation - Micro-Finance Scheme","authority_url":"https://www.nmdfc.org/","canonical_url":"https://www.nmdfc.org/nmdfcschemes","source_url":"https://www.nmdfc.org/nmdfcschemes","source_kind":"agency","source_title":"NMDFC current schemes page","source_anchor":"Micro-Finance Scheme: SHG members, minority women focus, Credit Line 1/2 member and group ceilings, interest and repayment","summary":"Micro-credit for members of Self Help Groups, with a particular focus on minority women in remote villages and urban slums, routed through State Channelizing Agencies.","objective":"Provide quick, small-scale credit for income-generating activity through organized Self Help Groups that practice thrift and credit.","legal_basis":"NMDFC official current schemes, FAQ and micro-finance guideline pages; SCA and SHG documentation control the live application.","eligibility":{"entity_types":["self_help_group","minority_woman_shg_member","minority_shg_member"],"lifecycle_stages":["starting","operating"],"industries":["micro_business","retail","services","artisan","agriculture_and_allied","home_based_activity"],"locations":["India","rural_area","urban_area","urban_slum"],"conditions":["beneficiary must belong to a notified minority community under the selected current credit line","beneficiaries must be organized into an eligible SHG and satisfy thrift, credit and SCA requirements","Credit Line 1 and Credit Line 2 have different income, member-level, group-level, interest and repayment terms","the route is implemented through State Channelizing Agencies and current SHG/partner rules","women-focused and minority-composition conditions must be verified against the current guideline and SCA"],"thresholds":{"credit_line_1_member_loan_max_inr":100000,"credit_line_1_group_loan_max_inr":2000000,"credit_line_2_member_loan_max_inr":150000,"credit_line_2_group_loan_max_inr":3000000,"credit_line_1_annual_family_income_max_inr":300000,"credit_line_2_annual_family_income_max_inr":800000,"credit_line_1_interest_percent":7,"credit_line_2_interest_percent_male":10,"credit_line_2_interest_percent_women":8,"beneficiary_repayment_max_years":3},"unknown_handling":"needs_information"},"application":{"portal":"https://www.nmdfc.org/guidelines_for_micro_financing_schemes","route":"Form or join an eligible Self Help Group, complete thrift/credit and minority/income documentation, and apply through the relevant State Channelizing Agency under its current micro-finance process.","selection":"The SHG, SCA and implementing partners verify group/member eligibility, project/activity and repayment structure; UdyamVeda cannot sanction or disburse credit.","fees":"The reviewed sources do not establish a universal applicant fee. SCA, SHG, documentation, interest and other current terms must be confirmed before application.","applicant_note":"UdyamVeda may explain the group route and checklist, but must not impersonate an SHG member or SCA or promise group approval."},"fine_print":{"structure":"The current NMDFC page describes micro-credit to SHG members, especially minority women, through SCAs; group formation and thrift/credit discipline are part of the route.","credit_lines":"Current summary values are up to INR 1 lakh per member and INR 20 lakh for a group under Credit Line 1, and up to INR 1.5 lakh per member and INR 30 lakh for a group under Credit Line 2, with separate rates and women concessions.","repayment":"The current summary states a 3-year repayment period; current SCA agreement and guideline terms must be confirmed.","review_note":"Human review must confirm the current micro-finance guideline, SHG size/composition, income line, member/group ceiling, interest, women concession, thrift, SCA route, documents, repayment and amendments before publication."},"benefit_summary":{"types":["loan"],"summary":"Track-specific SHG micro-credit: current NMDFC pages describe member and group ceilings under two credit lines, with separate rates and women-focused concessions; no personal or group sanction is guaranteed.","separate_value_buckets":true},"benefit_type":"loan","benefit_label":"NMDFC SHG micro-credit with separate member and group ceilings by credit line","amount_min":null,"amount_max":3000000,"percentage":null,"benefit_conditions":{"credit_line_1_member_max_inr":100000,"credit_line_1_group_max_inr":2000000,"credit_line_2_member_max_inr":150000,"credit_line_2_group_max_inr":3000000,"shg_route_required":true,"sca_route_required":true,"loan_not_guaranteed":true},"requirement":"Eligible SHG, minority and income evidence, thrift/credit records and viable micro-activity information","requirement_description":"Provide SHG/member records, minority and income certificates, KYC, residence proof, thrift/credit information, activity/project details and current SCA forms or declarations.","rules":{"all":[{"field":"eligible_shg_verified","operator":"equals","value":true},{"field":"notified_minority_status_verified","operator":"equals","value":true},{"field":"annual_family_income_inr","operator":"less_than_or_equal","value":800000},{"field":"sca_microfinance_route_available","operator":"equals","value":true}],"unknown_handling":"needs_information"},"steps":[{"title":"Confirm SHG and current credit line","description":"Verify group composition, member eligibility, income line, member/group ceiling and women concession under the current guideline.","url":"https://www.nmdfc.org/nmdfcschemes"},{"title":"Prepare group and member records","description":"Collect SHG formation, thrift/credit, minority, income, residence, KYC and activity evidence.","url":"https://www.nmdfc.org/guidelines_for_micro_financing_schemes"},{"title":"Apply through the SCA","description":"Submit the SHG route through the relevant State Channelizing Agency and follow its current appraisal and documentation process.","url":"https://www.nmdfc.org/faq"},{"title":"Complete disbursement and repayment setup","description":"Confirm member/group sanction, rate, contribution, moratorium if any, repayment and monitoring obligations before accepting funds.","url":"https://www.nmdfc.org/nmdfcschemes"}],"window_type":"rolling","window_close_at":null,"window_label":"Rolling SCA-led micro-finance route; no single nationwide closing date is stated in the reviewed sources.","window_evidence":{"source_url":"https://www.nmdfc.org/nmdfcschemes","anchor":"Current page describes a standing Micro-Finance Scheme implemented through SCAs."},"review_note":"Keep review-gated. Show member and group values separately and never combine them into one applicant amount."},
      {"slug":"nmdfc-virasat-artisan-credit","name":"NMDFC Virasat Credit Scheme for Craftpersons","type":"artisan_credit","status":"active","authority":"National Minorities Development and Finance Corporation - Virasat Scheme","authority_url":"https://www.nmdfc.org/","canonical_url":"https://www.nmdfc.org/nmdfcschemes","source_url":"https://www.nmdfc.org/nmdfcschemes","source_kind":"agency","source_title":"NMDFC current schemes page","source_anchor":"Virasat Scheme: artisan working/fixed capital, maximum credit, interest, women concession, contribution and repayment","summary":"Credit for minority craftpersons and artisans to purchase tools, equipment, machinery and raw material for working-capital and fixed-capital requirements.","objective":"Strengthen minority artisan livelihoods and productive capacity through concessional credit for equipment, tools, machinery and raw material.","legal_basis":"NMDFC official current schemes page and related Virasat/credit-line materials; current artisan and SCA guidelines control the live case.","eligibility":{"entity_types":["minority_artisan","craftsperson","artisan_shg_member","small_artisan_business"],"lifecycle_stages":["starting","operating","expanding"],"industries":["handicrafts","handloom","traditional_occupations","artisan_manufacturing","home_based_production"],"locations":["India","rural_area","urban_area"],"conditions":["applicant must belong to a notified minority community and be engaged in an eligible craft/artisan occupation","credit may support working capital and fixed capital for equipment, tools, machinery or raw material","Credit Line 1 and Credit Line 2 income and interest conditions apply","application is routed through the relevant SCA/partner and requires current artisan/activity evidence","female artisan rate concession is subject to current scheme terms"],"thresholds":{"credit_line_1_annual_family_income_max_inr":300000,"credit_line_2_annual_family_income_max_inr":800000,"loan_ceiling_inr":1000000,"credit_line_1_interest_percent":5,"credit_line_2_interest_percent_male":6,"female_artisan_rate_concession_percent":1,"beneficiary_repayment_max_years":5,"moratorium_months":6},"unknown_handling":"needs_information"},"application":{"portal":"https://www.nmdfc.org/nmdfcschemes","route":"Confirm the eligible craft/activity, prepare minority, income, residence, KYC and equipment/raw-material evidence, and apply through the relevant SCA or current NMDFC partner route.","selection":"The SCA/partner validates artisan activity, project cost, contribution, documentation and repayment capacity; UdyamVeda cannot approve or disburse the credit.","fees":"No universal applicant fee is established by the reviewed sources. Contribution, interest, processing, security, insurance and SCA terms require current confirmation.","applicant_note":"UdyamVeda may prepare the artisan-credit checklist, but must not represent itself as NMDFC or submit in the applicant's place."},"fine_print":{"purpose":"The current NMDFC schemes page describes Virasat as part of the Term Loan framework for working capital and fixed capital to purchase equipment/tools/machinery/raw material.","quantum":"The current summary describes maximum credit up to INR 10 lakh under Credit Lines 1 and 2, with 5% interest under Credit Line 1, 6% for male artisans under Credit Line 2 and a 1% concession for female artisans; current guidelines must be confirmed.","repayment":"The current summary states a 6-month moratorium and 5-year beneficiary repayment period; current SCA terms control.","review_note":"Human review must verify the current Virasat guideline, artisan definition, income line, craft/activity documents, project cost, contribution, rates, women concession, repayment, security, monitoring and amendments before publication."},"benefit_summary":{"types":["loan","market_access"],"summary":"Concessional artisan credit up to the current stated INR 10 lakh ceiling for eligible minority craftpersons' tools, equipment, machinery and raw material, subject to SCA appraisal and current terms.","separate_value_buckets":true},"benefit_type":"loan","benefit_label":"NMDFC Virasat artisan credit: up to INR 10 lakh, subject to current SCA and scheme conditions","amount_min":null,"amount_max":1000000,"percentage":null,"benefit_conditions":{"working_and_fixed_capital":true,"credit_line_specific_terms":true,"female_artisan_concession_possible":true,"sca_route_required":true,"loan_not_guaranteed":true},"requirement":"Minority/artisan evidence, income and KYC documents, activity proof and equipment/raw-material project details","requirement_description":"Provide minority and income certificates, residence/KYC, artisan or craft activity evidence, project report/cost estimates, equipment/tool/raw-material quotations, contribution evidence and current SCA documents.","rules":{"all":[{"field":"notified_minority_status_verified","operator":"equals","value":true},{"field":"eligible_artisan_activity_verified","operator":"equals","value":true},{"field":"annual_family_income_inr","operator":"less_than_or_equal","value":800000},{"field":"sca_or_partner_route_available","operator":"equals","value":true}],"unknown_handling":"needs_information"},"steps":[{"title":"Confirm artisan and Virasat eligibility","description":"Verify minority status, craft activity, income line, current ceiling and female-artisan concession under the controlling material.","url":"https://www.nmdfc.org/nmdfcschemes"},{"title":"Prepare activity and project evidence","description":"Collect craft/activity proof, equipment or raw-material quotations, project report, KYC, income and contribution records.","url":"https://www.nmdfc.org/home/nmdfc_schemes"},{"title":"Apply through the SCA or partner","description":"Submit the current Virasat route through the relevant SCA/partner and complete its appraisal and documentation process.","url":"https://www.nmdfc.org/faq"},{"title":"Complete disbursement and repayment setup","description":"Confirm the final contribution, rate, moratorium, repayment, utilization and monitoring terms before accepting the credit.","url":"https://www.nmdfc.org/nmdfcschemes"}],"window_type":"rolling","window_close_at":null,"window_close_at":null,"window_label":"Rolling artisan-credit route; local SCA availability and current Virasat terms must be confirmed.","window_evidence":{"source_url":"https://www.nmdfc.org/nmdfcschemes","anchor":"Current page describes Virasat as a standing artisan credit scheme without a single nationwide closing date."},"review_note":"Keep review-gated. Do not present the artisan ceiling as a grant or as an automatic entitlement."}
    ]$records$::jsonb)
  loop
    authority_id := null;
    insert into public.authorities (name, level, ministry, department, official_url)
    select item->>'authority', 'central', 'Ministry of Minority Affairs', 'National Minorities Development and Finance Corporation', item->>'authority_url'
    where not exists (select 1 from public.authorities where name = item->>'authority')
    returning id into authority_id;
    if authority_id is null then select id into authority_id from public.authorities where name = item->>'authority' limit 1; end if;
    seed_opportunity_id := null;
    insert into public.opportunities (slug, name, opportunity_type, status, authority_id, geography, canonical_url)
    values (item->>'slug', item->>'name', item->>'type', item->>'status', authority_id, '{"coverage":"central","locations":["India"]}'::jsonb, item->>'canonical_url')
    on conflict (slug) do update set name = excluded.name, status = excluded.status, authority_id = excluded.authority_id, canonical_url = excluded.canonical_url
    returning id into seed_opportunity_id;
    if seed_opportunity_id is null then select id into seed_opportunity_id from public.opportunities where slug = item->>'slug' limit 1; end if;
    version_id := null;
    insert into public.opportunity_versions
      (opportunity_id, version_number, title, summary, objective, legal_basis, eligibility, application, fine_print, benefit_summary, last_verified_at, completeness, confidence, review_status)
    values (seed_opportunity_id, 1, item->>'name', item->>'summary', item->>'objective', item->>'legal_basis', item->'eligibility', item->'application', item->'fine_print', item->'benefit_summary', now(), 0.89, 0.85, 'in_review')
    on conflict (opportunity_id, version_number) do nothing
    returning id into version_id;
    if version_id is null then select ov.id into version_id from public.opportunity_versions ov where ov.opportunity_id = seed_opportunity_id and ov.version_number = 1 limit 1; end if;
    update public.opportunities set current_version_id = version_id, status = item->>'status' where id = seed_opportunity_id;
    insert into public.opportunity_sources (opportunity_version_id, source_url, source_kind, source_title, source_anchor, fetched_at, is_primary)
    values
      (version_id, item->>'source_url', item->>'source_kind', item->>'source_title', item->>'source_anchor', now(), true),
      (version_id, 'https://www.nmdfc.org/faq', 'agency', 'NMDFC current FAQ', 'Credit lines, application route and product terms', now(), false),
      (version_id, 'https://www.nmdfc.org/credit-1', 'agency', 'NMDFC Credit Line 1 detail', 'Credit Line 1 project-cost and contribution details', now(), false),
      (version_id, 'https://www.nmdfc.org/home/nmdfc_schemes', 'agency', 'NMDFC scheme landing page', 'Current scheme summary and document list', now(), false),
      (version_id, 'https://minorityaffairs.gov.in/WriteReadData/RTF1984/1953017398.pdf', 'guideline', 'Ministry of Minority Affairs NMDFC booklet', 'Cross-check of NMDFC term and micro-finance boundaries', now(), false)
    on conflict do nothing;
    insert into public.opportunity_benefits (opportunity_version_id, benefit_type, label, amount_min, amount_max, percentage, conditions)
    select version_id, item->>'benefit_type', item->>'benefit_label', (item->>'amount_min')::numeric, (item->>'amount_max')::numeric, (item->>'percentage')::numeric, item->'benefit_conditions'
    where not exists (select 1 from public.opportunity_benefits where opportunity_version_id = version_id and label = item->>'benefit_label');
    insert into public.opportunity_requirements (opportunity_version_id, requirement_type, name, description, required)
    select version_id, 'document', item->>'requirement', item->>'requirement_description', true
    where not exists (select 1 from public.opportunity_requirements where opportunity_version_id = version_id and name = item->>'requirement');
    insert into public.eligibility_rule_sets (opportunity_version_id, rules, source_evidence, reviewed)
    select version_id, item->'rules', jsonb_build_array(jsonb_build_object('source_url', item->>'source_url', 'anchor', item->>'source_anchor')), false
    where not exists (select 1 from public.eligibility_rule_sets where opportunity_version_id = version_id);
    insert into public.opportunity_steps (opportunity_version_id, step_number, title, description, official_url)
    select version_id, row_number() over ()::integer, step->>'title', step->>'description', step->>'url'
    from jsonb_array_elements(item->'steps') as steps(step)
    where not exists (select 1 from public.opportunity_steps where opportunity_version_id = version_id);
    insert into public.opportunity_windows (opportunity_version_id, window_type, closes_at, label, source_evidence)
    select version_id, item->>'window_type', (item->>'window_close_at')::timestamptz, item->>'window_label', item->'window_evidence'
    where not exists (select 1 from public.opportunity_windows where opportunity_version_id = version_id);
    insert into public.review_tasks (opportunity_version_id, task_type, status)
    select version_id, 'publish', 'open'
    where not exists (select 1 from public.review_tasks where opportunity_version_id = version_id and task_type = 'publish' and status in ('open', 'in_review'));
  end loop;
end $$;
